import type { EvalPath, EvalResult, PathMetrics } from './eval-runner.js';
import type { GoldenCase } from './golden-set.types.js';

/**
 * Отчёт eval (#926): числа до/после, промахи, полка, покрытие каталога.
 * Генерируется из прогона (`eval-runner.ts`) — руками не редактируется;
 * свежесть проверяет `eval-report.test.ts`, обновление — команда в шапке
 * `docs/architecture/assistant-eval-report.md`.
 */

export const EVAL_REPORT_MARKER =
  'GENERATED by UPDATE_ASSISTANT_EVAL_REPORT=1 pnpm --filter @nodus/api exec vitest run src/modules/assistant/eval/eval-report.test.ts';

const PATH_LABEL: Record<EvalPath, string> = {
  search: 'tools.search',
  router: 'диспетчер (симулятор)',
};

function pct(value: number): string {
  return `${(value * 100).toFixed(1)}%`;
}

function metricsRow(metrics: PathMetrics, path: EvalPath): string {
  return `| ${PATH_LABEL[path]} | ${pct(metrics.recallAt7)} | ${pct(metrics.allExpectedAt7)} | ${pct(metrics.wrongToolRate)} | ${pct(metrics.forbiddenShelfRate)} | ${pct(metrics.refusalAccuracy)} | ${pct(metrics.clarifySafety)} | ${pct(metrics.top1Accuracy)} |`;
}

function caseList(outcomes: EvalResult['outcomes'], path: EvalPath, limit = 12): string[] {
  const lines: string[] = [];
  for (const outcome of outcomes) {
    const expected = outcome.testCase.expectedTools;
    if (expected.length === 0) continue;
    const top = path === 'search' ? outcome.searchTop : outcome.routerTop;
    const missing = expected.filter((id) => !top.includes(id));
    if (missing.length === 0) continue;
    lines.push(
      `- \`${outcome.testCase.id}\` (${outcome.testCase.role}): «${clipQuery(outcome.testCase.query)}» — нет ${missing.map((id) => `\`${id}\``).join(', ')}; top-7: ${top.map((id) => `\`${id}\``).join(', ') || '—'}`,
    );
    if (lines.length >= limit) break;
  }
  return lines;
}

function wrongList(outcomes: EvalResult['outcomes'], path: EvalPath, limit = 10): string[] {
  return outcomes
    .filter((outcome) => outcome.forbiddenHits[path].length > 0)
    .slice(0, limit)
    .map(
      (outcome) =>
        `- \`${outcome.testCase.id}\` (${outcome.testCase.role}): «${clipQuery(outcome.testCase.query)}» — запрещённые ${outcome.forbiddenHits[path].map((id) => `\`${id}\``).join(', ')}`,
    );
}

function refusalList(outcomes: EvalResult['outcomes']): string[] {
  return outcomes
    .filter((outcome) => outcome.testCase.noToolCase && outcome.refusalOk.router === false)
    .map(
      (outcome) =>
        `- \`${outcome.testCase.id}\`: «${clipQuery(outcome.testCase.query)}» — top-7: ${outcome.routerTop.map((id) => `\`${id}\``).join(', ') || '—'}`,
    );
}

function clarifyList(outcomes: EvalResult['outcomes']): string[] {
  return outcomes
    .filter((outcome) => outcome.testCase.shouldClarify && outcome.clarifyOk.router === false)
    .map(
      (outcome) =>
        `- \`${outcome.testCase.id}\`: «${clipQuery(outcome.testCase.query)}» — top-7: ${outcome.routerTop.map((id) => `\`${id}\``).join(', ') || '—'}`,
    );
}

function clipQuery(query: string): string {
  const single = query.replace(/\s+/g, ' ').trim();
  return single.length <= 90 ? single : `${single.slice(0, 89)}…`;
}

export interface BaselineMetrics {
  router: PathMetrics;
  search: PathMetrics;
}

function baselineBlock(baseline: BaselineMetrics | null, current: EvalResult): string[] {
  if (!baseline) {
    return ['_Baseline не зафиксирован: отчёт до изменений каталога ещё не снят._'];
  }
  return [
    '| Метрика | До (baseline) | После |',
    '| --- | --- | --- |',
    `| recall@7 (диспетчер) | ${pct(baseline.router.recallAt7)} | ${pct(current.router.recallAt7)} |`,
    `| все ожидаемые в top-7 (диспетчер) | ${pct(baseline.router.allExpectedAt7)} | ${pct(current.router.allExpectedAt7)} |`,
    `| recall@7 (tools.search) | ${pct(baseline.search.recallAt7)} | ${pct(current.search.recallAt7)} |`,
    `| неверный инструмент (выбран) | ${pct(baseline.router.wrongToolRate)} | ${pct(current.router.wrongToolRate)} |`,
    `| корректный отказ (диспетчер) | ${pct(baseline.router.refusalAccuracy)} | ${pct(current.router.refusalAccuracy)} |`,
  ];
}

export function renderEvalReport(
  result: EvalResult,
  options: { baseline?: BaselineMetrics | null; generatedFrom?: string } = {},
): string {
  const baseline = options.baseline ?? null;
  const rows = (['search', 'router'] as const).map((path) =>
    metricsRow(path === 'search' ? result.search : result.router, path),
  );
  const roleRows = (
    Object.entries(result.byRole) as [
      keyof EvalResult['byRole'],
      EvalResult['byRole'][keyof EvalResult['byRole']],
    ][]
  ).map(
    ([role, value]) =>
      `| ${role} | ${value.cases} | ${pct(value.router.recallAt7)} | ${pct(value.router.wrongToolRate)} | ${pct(value.router.refusalAccuracy)} |`,
  );
  const splitRows = (
    Object.entries(result.bySplit) as [
      keyof EvalResult['bySplit'],
      EvalResult['bySplit'][keyof EvalResult['bySplit']],
    ][]
  ).map(
    ([split, value]) =>
      `| ${split} | ${value.cases} | ${pct(value.router.recallAt7)} | ${pct(value.router.allExpectedAt7)} | ${pct(value.router.wrongToolRate)} |`,
  );
  const frequency = result.shelf.frequency
    .slice(0, 20)
    .map((entry) => `| \`${entry.id}\` | ${entry.count} | ${entry.hot ? 'да' : 'нет'} |`);
  const misses = caseList(result.outcomes, 'router');
  const wrong = wrongList(result.outcomes, 'router');
  const refusals = refusalList(result.outcomes);
  const clarify = clarifyList(result.outcomes);
  return [
    '# Eval каталога инструментов ассистента (#926)',
    '',
    `<!-- ${EVAL_REPORT_MARKER}: не редактируй руками. -->`,
    '',
    'Золотой набор реальных запросов четырёх ролей + детерминированный прогон',
    'двух траекторий выбора: лексический `tools.search` и симулятор диспетчера',
    `(единый скорер, версия ${result.retrievalVersion}). Модель и сеть не нужны —`,
    'прогон воспроизводим и является CI-гейтом (`eval-gate.test.ts`).',
    '',
    `Источник: ${options.generatedFrom ?? 'каталог ветки; золотой набор `eval/golden`'}.`,
    `Кейсов: **${result.caseCount}** (с инструментами ${result.supportedCount}, без инструмента ${result.noToolCount}, уточнение ${result.clarifyCount}); инструментов в каталоге: **${result.catalogSize}**.`,
    '',
    '## Итог',
    '',
    '| Траектория | recall@7 | все ожидаемые в top-7 | неверный (выбран) | запрещён в полке | корректный отказ | безопасное уточнение | top-1 |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |',
    ...rows,
    '',
    'Пороги гейта: recall@7 ≥ 90%, неверный инструмент (выбран первым) < 5%,',
    'корректный отказ ≥ 95%, безопасное уточнение ≥ 90%. Запрещённый инструмент',
    'в полке top-7 — справочное число: полка это кандидаты, решение принимает модель.',
    'Считаются на всём наборе; dev/holdout — контроль переобучения.',
    '',
    '## По ролям (диспетчер)',
    '',
    '| Роль | Кейсов | recall@7 | неверный | отказ |',
    '| --- | --- | --- | --- | --- |',
    ...roleRows,
    '',
    '## Dev / holdout',
    '',
    '| Часть | Кейсов | recall@7 | все ожидаемые | неверный |',
    '| --- | --- | --- | --- | --- |',
    ...splitRows,
    '',
    '## До / после',
    '',
    ...baselineBlock(baseline, result),
    '',
    '## Промахи выбора (диспетчер, до 12)',
    '',
    ...(misses.length > 0 ? misses : ['—']),
    '',
    '## Запрещённые инструменты в полке (справочно, до 10)',
    '',
    ...(wrong.length > 0 ? wrong : ['—']),
    '',
    '## Отказы: инструмента нет, а модель «натянула» (до 10)',
    '',
    ...(refusals.length > 0 ? refusals : ['—']),
    '',
    '## Уточнения: действие без имени/id (до 10)',
    '',
    ...(clarify.length > 0 ? clarify : ['—']),
    '',
    '## Горячая полка',
    '',
    `Сейчас: **${result.shelf.hotSize}** инструментов; ожидаемые инструменты полки покрывают **${pct(result.shelf.hotRecall)}** запросов, полный набор кейса — **${pct(result.shelf.hotCaseCoverage)}**.`,
    `Предложение 12–15 по частоте золотого набора: ${result.shelf.suggestedHot.map((id) => `\`${id}\``).join(', ') || '—'}.`,
    `Не на полке, но частые: ${result.shelf.missingFromCurrentHot.map((id) => `\`${id}\``).join(', ') || '—'}.`,
    `На полке, но не в предложении: ${result.shelf.extraInCurrentHot.map((id) => `\`${id}\``).join(', ') || '—'}.`,
    '',
    '| Инструмент | Ожиданий в наборе | На полке сейчас |',
    '| --- | --- | --- |',
    ...frequency,
    '',
    '## Покрытие каталога',
    '',
    `Золотой набор упоминает **${result.catalogCoverage.expected}** из **${result.catalogCoverage.total}** инструментов каталога.`,
    `Не упомянуты: ${result.catalogCoverage.unmentioned.map((id) => `\`${id}\``).join(', ') || '—'}.`,
    '',
  ].join('\n');
}

/** Компактная сводка для консоли теста. */
export function summaryLine(result: EvalResult): string {
  return [
    `search: recall@7 ${pct(result.search.recallAt7)}, неверный ${pct(result.search.wrongToolRate)}`,
    `router: recall@7 ${pct(result.router.recallAt7)}, неверный ${pct(result.router.wrongToolRate)}, отказ ${pct(result.router.refusalAccuracy)}`,
  ].join(' | ');
}

/** Тип для данных baseline (генерируются прогоном на каталоге до изменений). */
export interface BaselineSnapshot {
  source: string;
  retrievalVersion: string;
  router: PathMetrics;
  search: PathMetrics;
  byRole?: Record<string, { cases: number; router: PathMetrics }>;
  cases?: GoldenCase[];
}
